/**
 * 进程级配置来源
 *
 * 用途：让调用方（如 CloudBase CLI）提前告诉 toolbox「本次命令的项目目录 / 配置文件在哪」，
 * 使 getRegion 等内部读配置的逻辑不再固定读取 process.cwd()。
 *
 * 兼容性：默认不设置，getConfigSource() 返回空对象，所有分支回退到原有行为
 * （process.cwd() 与既有的 yargs 参数解析），对现有调用方零影响。
 */
export interface IConfigSource {
    /** 配置搜索与相对路径的基准目录（绝对路径） */
    cwd?: string;
    /** 明确的配置文件路径（绝对路径），优先级高于 cwd */
    configPath?: string;
}
/** 设置本次进程的配置来源；未传的字段表示「沿用原有行为」 */
export declare function setConfigSource(source?: IConfigSource): void;
/** 读取当前配置来源；始终返回副本，避免调用方意外修改内部状态 */
export declare function getConfigSource(): IConfigSource;
/** 清空配置来源（仅供测试与长驻进程重置使用） */
export declare function resetConfigSource(): void;
